import { line } from 'axylo';

/**
 * Draws the daily signups as a line chart.
 *
 * @param {HTMLElement} element the chart container
 * @param {ReadonlyArray<{ day: string, signpus: number | null }>} data the rows from data.json
 * @returns the Axylo chart handle
 */
export default function render(element, data) {
  return line(element, {
    title: 'Daily signups',
    data,
    // 'YYYY-MM-DD' strings are read as calendar dates, the same in every time zone.
    x: 'day',
    // The rows spell this key "signpus"; the field must match the data (else AX101),
    // and the label gives readers the correct word on the axis, tooltip and table.
    y: { field: 'signpus', label: 'Signups' },
  });
}

