input.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render from './chart.js';

const data = JSON.parse(readFileSync('data.json', 'utf8'));
console.log('default export:', typeof render, 'arity', render.length);

const opts = { title: 'Daily signups', data, x: 'day', y: { field: 'signpus', label: 'Signups' } };
const problems = validate('line', opts);
console.log('chart.js options ->', problems.length, 'diagnostics');
for (const d of problems) console.log(' ', d.code, d.level, d.message);

const typo = validate('line', { ...opts, y: { field: 'signups', label: 'Signups' } });
console.log('with field \"signups\" ->');
for (const d of typo) console.log(' ', d.code, d.level, d.message);
"

